function validate([skill, mana]) {
  if (skill.length < 1 || skill.length > 5000) return 'skill needs 1 to 5000 values.';
  if (mana.length < 1 || mana.length > 5000) return 'mana needs 1 to 5000 values.';
  if (skill.some(v => !Number.isInteger(v) || v < 1 || v > 5000)) return 'Each skill is an integer from 1 to 5000.';
  if (mana.some(v => !Number.isInteger(v) || v < 1 || v > 5000)) return 'Each mana value is an integer from 1 to 5000.';
  return null;
}

