function minTime(skill, mana) {
  const n = skill.length;
  const finish = new Array(n).fill(0);
  for (const amount of mana) {
    let start = finish[0];
    for (let i = 1; i < n; i++) {
      start = Math.max(start + skill[i - 1] * amount, finish[i]);
    }
    finish[n - 1] = start + skill[n - 1] * amount;
    for (let i = n - 2; i >= 0; i--) {
      finish[i] = finish[i + 1] - skill[i + 1] * amount;
    }
  }
  return finish[n - 1];
}

