function minTime(skill, mana) {
  const n = skill.length;
  // busy[i] is when wizard i finishes the previous potion.
  let busy = new Array(n).fill(0);
  let begin = 0;
  for (const amount of mana) {
    // Try to start the potion at begin; if some wizard is still busy when it would arrive, push begin back by
    // exactly that gap and check every wizard again. begin only grows, so this stops at the earliest valid start.
    for (;;) {
      let arrive = begin, delay = 0;
      for (let i = 0; i < n; i++) {
        if (arrive < busy[i]) { delay = busy[i] - arrive; break; }
        arrive += skill[i] * amount;
      }
      if (delay === 0) break;
      begin += delay;
    }
    const next = [];
    let time = begin;
    for (let i = 0; i < n; i++) { time += skill[i] * amount; next.push(time); }
    busy = next;
  }
  return busy[n - 1];
}

