function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const pick = (top) => {
    const kind = rand();
    if (kind < 0.15) return 1;
    if (kind < 0.25) return 5000;
    return int(1, top);
  };
  if (size === 'large') {
    const n = int(1000, 2000), m = int(400, 700);
    const top = rand() < 0.5 ? 5000 : 50;
    return [Array.from({ length: n }, () => pick(top)), Array.from({ length: m }, () => pick(top))];
  }
  const n = int(1, 6), m = int(1, 6);
  const top = rand() < 0.6 ? 10 : 5000;
  const same = rand() < 0.15;
  const skill = Array.from({ length: n }, () => pick(top));
  const mana = Array.from({ length: m }, () => pick(top));
  if (same) { skill.fill(skill[0]); mana.fill(mana[0]); }
  return [skill, mana];
}
